rendering.css:
:root {
  --primary: #6366f1;
  --accent: #a855f7;
  --bg-main: #090d16;
  --bg-surface: #111827;
  --bg-card: #1f2937;
  --text-main: #f9fafb;
  --text-muted: #9ca3af;
  --border: #374151;
  --focus: #818cf8;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background-color: var(--bg-main); color: var(--text-main); line-height: 1.6; }
.container { max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }
a { color: inherit; text-decoration: none; }
:focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }
.site-header { background: rgba(9, 13, 22, 0.95); backdrop-filter: blur(12px); position: sticky; top: 0; z-index: 100; border-bottom: 1px solid var(--border); }
.header-inner { display: flex; align-items: center; justify-content: space-between; height: 72px; }
.brand-logo { display: flex; align-items: center; gap: 0.75rem; font-weight: 700; font-size: 1.25rem; }
.brand-badge { background: linear-gradient(135deg, var(--primary), var(--accent)); color: #fff; font-size: 0.65rem; padding: 2px 6px; border-radius: 4px; font-weight: 800; }
.nav-menu { display: flex; gap: 1.5rem; }
.nav-link { font-size: 0.9rem; color: var(--text-muted); transition: color 0.2s; }
.nav-link:hover { color: #fff; }
.btn { display: inline-flex; align-items: center; justify-content: center; padding: 0.65rem 1.35rem; border-radius: 8px; font-weight: 700; font-size: 0.875rem; transition: all 0.2s; cursor: pointer; border: 1px solid transparent; min-height: 44px; }
.btn-tech { background: linear-gradient(135deg, #6366f1 0%, #a855f7 100%); color: #fff; }
.btn-tech:hover { filter: brightness(1.15); box-shadow: 0 0 20px rgba(99, 102, 241, 0.4); }
.btn-outline { border-color: var(--border); background: transparent; color: var(--text-main); }
.btn-outline:hover { background: var(--bg-surface); }
.btn-full { width: 100%; }
.btn-lg { padding: 0.85rem 1.75rem; font-size: 1rem; }
.hero-section { position: relative; min-height: 75vh; display: flex; align-items: center; justify-content: center; text-align: center; background: radial-gradient(circle at center, rgba(99, 102, 241, 0.15) 0%, #090d16 100%); padding: 5rem 0; }
.hero-badge { display: inline-block; padding: 0.35rem 1rem; border-radius: 9999px; background: rgba(99, 102, 241, 0.15); border: 1px solid var(--primary); color: #a5b4fc; font-size: 0.8rem; font-weight: 700; margin-bottom: 1.5rem; }
.hero-title { font-size: 3.5rem; font-weight: 800; line-height: 1.1; margin-bottom: 1.25rem; color: #fff; }
.hero-desc { max-width: 720px; margin: 0 auto 2.5rem; color: var(--text-muted); font-size: 1.125rem; }
.hero-ctas { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }
.section { padding: 5rem 0; }
.section-head { margin-bottom: 3.5rem; }
.section-kicker { font-size: 0.8rem; font-weight: 700; color: #a5b4fc; text-transform: uppercase; letter-spacing: 2px; }
.section-title { font-size: 2.25rem; font-weight: 800; margin: 0.5rem 0; color: #fff; }
.section-subtitle { color: var(--text-muted); }
.text-center { text-align: center; }
.bento-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.5rem; }
.bento-card { background: var(--bg-surface); border: 1px solid var(--border); border-radius: 12px; padding: 2rem; }
.bento-card h3 { color: #fff; margin-bottom: 0.75rem; font-size: 1.25rem; }
.bento-card p { color: var(--text-muted); font-size: 0.95rem; }
.card-tag { font-size: 0.75rem; color: #a5b4fc; font-weight: 700; text-transform: uppercase; }
.pricing-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 2rem; max-width: 1080px; margin: 0 auto; }
.price-card { background: var(--bg-surface); border: 1px solid var(--border); border-radius: 16px; padding: 2.5rem; position: relative; display: flex; flex-direction: column; justify-content: space-between; }
.price-popular { border-color: var(--primary); box-shadow: 0 0 30px rgba(99, 102, 241, 0.2); }
.popular-badge { position: absolute; top: -12px; left: 50%; transform: translateX(-50%); background: var(--primary); color: #fff; font-size: 0.75rem; font-weight: 800; padding: 3px 12px; border-radius: 9999px; }
.price-tier { font-size: 1.25rem; color: #fff; margin-bottom: 0.5rem; }
.price-val { font-size: 2.5rem; font-weight: 800; color: #fff; margin-bottom: 0.5rem; }
.price-val span { font-size: 1rem; color: var(--text-muted); font-weight: 400; }
.price-desc { color: var(--text-muted); font-size: 0.875rem; margin-bottom: 1.5rem; }
.price-features { list-style: none; margin-bottom: 2rem; }
.price-features li { margin-bottom: 0.6rem; font-size: 0.9rem; color: var(--text-muted); }
.site-footer { border-top: 1px solid var(--border); background: #060911; padding: 4rem 0 2rem; color: var(--text-muted); }
.footer-inner { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 2.5rem; }
.footer-col h3, .footer-col h4 { color: #fff; margin-bottom: 1rem; }
@media (max-width: 768px) { .nav-menu { display: none; } .hero-title { font-size: 2.25rem; } }
